// ── common.mjs ──
const GRAVEDADES = ['critica', 'alta', 'media', 'baja', 'info'];
const ORDEN_GRAVEDAD = { critica: 0, alta: 1, media: 2, baja: 3, info: 4 };

function bytesUtf8(texto) {
  const t = String(texto ?? '');
  let n = 0;
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < t.length && t.charCodeAt(i + 1) >= 0xdc00 && t.charCodeAt(i + 1) <= 0xdfff) { n += 4; i++; }
    else n += 3;
  }
  return n;
}

function plegar(texto) {
  return String(texto ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function recortar(texto, max = 120) {
  const t = String(texto ?? '').replace(/\s+/g, ' ').trim();
  return t.length <= max ? t : `${t.slice(0, Math.max(0, max - 1))}…`;
}

function precioAnteriorDeclarado(p) {
  const n = Number(p?.declaredPreviousPrice ?? p?.originalPrice);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function mediana(numeros) {
  const v = numeros.filter((n) => Number.isFinite(n)).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
}

function euros(n) {
  return Number.isFinite(Number(n)) ? `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €` : 'sin precio';
}

function fechaValida(valor) {
  if (typeof valor !== 'string' || !valor) return null;
  const t = Date.parse(valor);
  return Number.isNaN(t) ? null : new Date(t).toISOString();
}

function diasEntre(desdeIso, hastaIso) {
  const a = Date.parse(desdeIso);
  const b = Date.parse(hastaIso);
  return Number.isNaN(a) || Number.isNaN(b) ? null : Math.floor((b - a) / 86400000);
}

function contarPor(lista, clave) {
  const out = {};
  for (const x of lista) {
    const k = String(clave(x) ?? '—');
    out[k] = (out[k] ?? 0) + 1;
  }
  return out;
}

function ordenarIncidencias(lista) {
  return [...lista].sort((a, b) => (ORDEN_GRAVEDAD[a.gravedad] ?? 9) - (ORDEN_GRAVEDAD[b.gravedad] ?? 9) || String(a.id).localeCompare(String(b.id)));
}

function resumenIncidencias(lista) {
  const c = { critica: 0, alta: 0, media: 0, baja: 0, info: 0 };
  for (const i of lista) if (c[i.gravedad] !== undefined) c[i.gravedad]++;
  return c;
}

function estadoGlobal(contador) {
  if (contador.critica > 0) return 'critico';
  if (contador.alta > 0 || contador.media > 0) return 'atencion';
  return 'ok';
}

function validarConfig(cfg) {
  const errores = [];
  if (!cfg || typeof cfg !== 'object') return ['configuración ausente'];
  if (typeof cfg.baseUrl !== 'string' || !/^https?:\/\//.test(cfg.baseUrl)) errores.push('baseUrl debe empezar por http(s)://');
  if (!Array.isArray(cfg.hostsPermitidos) || !cfg.hostsPermitidos.length) errores.push('hostsPermitidos es obligatorio');
  if (!['completo', 'publico'].includes(cfg.modo)) errores.push('modo debe ser completo o publico');
  if (!Array.isArray(cfg.rutas) || !cfg.rutas.length) errores.push('rutas es obligatorio');
  for (const k of ['maxEnlaces', 'maxPaginasCatalogo', 'limitePorPagina', 'maxFichas']) {
    if (!Number.isInteger(cfg[k]) || cfg[k] < 0 || cfg[k] > 500) errores.push(`${k} debe ser un entero entre 0 y 500`);
  }
  if (!cfg.umbrales || typeof cfg.umbrales !== 'object') errores.push('umbrales es obligatorio');
  return errores;
}

// ── urlPolicy.mjs ──
const RUTAS_PROHIBIDAS = [
  /^\/api(\/|$)/i,
  /^\/out(\/|$)/i,
  /^\/p(\/|$)/i,
  /^\/checkout(\/|$)/i,
  /^\/upayp1b4/i,
  /^\/admin(\/|$)/i,
  /^\/mi-radar(\/|$)/i,
  /^\/perfil(\/|$)/i,
  /^\/share(\/|$)/i,
  /^\/ejemplo-afiliados(\/|$)/i,
];

const RUTA_CATALOGO_AUTOMATIZACION = '/api/automation/v1/catalog';

const HOSTS_LOCALES = ['localhost', '127.0.0.1', 'puente-treidilor'];

const PUERTOS_POR_DEFECTO = { 'http:': '80', 'https:': '443' };

function analizarAbsoluta(texto) {
  const m = texto.match(/^(https?):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  const protocol = `${m[1].toLowerCase()}:`;
  let autoridad = m[2];
  let username = '';
  let password = '';
  const arroba = autoridad.lastIndexOf('@');
  if (arroba >= 0) {
    const info = autoridad.slice(0, arroba);
    autoridad = autoridad.slice(arroba + 1);
    const dos = info.indexOf(':');
    username = dos >= 0 ? info.slice(0, dos) : info;
    password = dos >= 0 ? info.slice(dos + 1) : '';
    if (!username && !password) username = '@';
  }
  const h = autoridad.match(/^([A-Za-z0-9.-]+)(?::(\d*))?$/);
  if (!h || !h[1]) return null;
  const hostname = h[1].toLowerCase();
  const port = h[2] && h[2] !== PUERTOS_POR_DEFECTO[protocol] ? h[2] : '';
  const pathname = m[3] || '/';
  const search = m[4] && m[4] !== '?' ? m[4] : '';
  const host = port ? `${hostname}:${port}` : hostname;
  const userinfo = username || password ? `${username}${password ? `:${password}` : ''}@` : '';
  return { protocol, username, password, host, hostname, port, pathname, search, hash: '', toString: () => `${protocol}//${userinfo}${host}${pathname}${search}` };
}

function normalizarUrl(valor, base) {
  const v = String(valor ?? '').replace(/[\t\r\n]/g, '').trim();
  if (!v || /[\\\s]/.test(v)) return null;
  const b = analizarAbsoluta(String(base ?? ''));
  if (/^[a-z][a-z0-9+.-]*:/i.test(v)) return analizarAbsoluta(v);
  if (!b) return null;
  if (v.startsWith('//')) return analizarAbsoluta(`${b.protocol}${v}`);
  const origen = `${b.protocol}//${b.host}`;
  if (v.startsWith('/')) return analizarAbsoluta(`${origen}${v}`);
  if (v.startsWith('?')) return analizarAbsoluta(`${origen}${b.pathname}${v}`);
  if (v.startsWith('#')) return analizarAbsoluta(`${origen}${b.pathname}${b.search}`);
  return analizarAbsoluta(`${origen}${b.pathname.slice(0, b.pathname.lastIndexOf('/') + 1)}${v}`);
}

function validarAislamiento(cfg) {
  const errores = [];
  const base = normalizarUrl(cfg?.baseUrl, undefined);
  if (!base) return ['baseUrl no válida'];
  const hosts = (cfg.hostsPermitidos ?? []).map((h) => String(h).split(':')[0].toLowerCase());
  if (cfg.entorno === 'local') {
    if (!HOSTS_LOCALES.includes(base.hostname)) errores.push(`entorno local con baseUrl no local (${base.hostname})`);
    for (const h of hosts) if (!HOSTS_LOCALES.includes(h) || /treidilor\.com/.test(h)) errores.push(`entorno local con host no local (${h})`);
  } else if (cfg.entorno === 'produccion') {
    if (base.protocol !== 'https:') errores.push('producción exige https');
    for (const h of [base.hostname, ...hosts]) if (HOSTS_LOCALES.includes(h)) errores.push(`producción con host local (${h})`);
  } else {
    errores.push(`entorno desconocido (${cfg.entorno})`);
  }
  return errores;
}

function evaluarUrl(valor, tipo, cfg) {
  const u = normalizarUrl(valor, cfg.baseUrl);
  if (!u) return { ok: false, motivo: 'url_no_valida' };
  if (cfg.entorno === 'local' && !HOSTS_LOCALES.includes(u.hostname)) return { ok: false, motivo: 'entorno_local_solo_hosts_locales' };
  if (cfg.entorno === 'produccion' && HOSTS_LOCALES.includes(u.hostname)) return { ok: false, motivo: 'entorno_produccion_sin_hosts_locales' };
  if (u.username || u.password) return { ok: false, motivo: 'credenciales_en_url' };
  if (!cfg.hostsPermitidos.includes(u.host)) return { ok: false, motivo: 'host_no_permitido' };
  const local = HOSTS_LOCALES.includes(u.hostname);
  if (u.protocol === 'http:' && !local) return { ok: false, motivo: 'http_fuera_de_local' };
  const ruta = u.pathname;
  if (ruta.includes('..') || /%2e|%2f|%5c/i.test(ruta)) return { ok: false, motivo: 'ruta_sospechosa' };
  if (tipo === 'salud') return ruta === '/api/health' ? { ok: true, url: u.toString() } : { ok: false, motivo: 'salud_solo_api_health' };
  if (tipo === 'catalogo') {
    if (cfg.modo !== 'completo') return { ok: false, motivo: 'catalogo_solo_modo_completo' };
    return ruta === RUTA_CATALOGO_AUTOMATIZACION ? { ok: true, url: u.toString() } : { ok: false, motivo: 'catalogo_ruta_no_permitida' };
  }
  if (RUTAS_PROHIBIDAS.some((r) => r.test(ruta))) return { ok: false, motivo: 'ruta_con_efectos' };
  if (tipo === 'ficha') {
    if (cfg.modo !== 'completo') return { ok: false, motivo: 'fichas_solo_modo_completo' };
    return /^\/producto\/[A-Za-z0-9_.~-]{1,160}$/.test(ruta) ? { ok: true, url: u.toString() } : { ok: false, motivo: 'ficha_ruta_no_valida' };
  }
  if (/^\/producto(\/|$)/i.test(ruta)) return { ok: false, motivo: 'ficha_visita_cuenta_en_analitica' };
  return { ok: true, url: u.toString() };
}

// ── seguimiento.mjs ──
const ESQUEMA_SEGUIMIENTO = 1;

const LIMITES_SEGUIMIENTO = {
  maxIncidencias: 200, // incidencias que conserva el estado
  maxBytesEstado: 65536, // tamaño máximo del estado serializado (UTF-8)
  maxResueltasRecientes: 30,
  maxAntiguedadDias: 14, // una referencia más antigua se descarta (línea base)
  diasReaparicion: 14, // ventana en la que una incidencia resuelta que vuelve se marca «reaparecida»
  maxEjecucionesSinVerificar: 7, // una incidencia «no verificada» tanto tiempo caduca
  umbralErroresParcial: 0.2, // más de este porcentaje de peticiones sin respuesta ⇒ ejecución parcial
  maxLongitudDestino: 120, // destinos más largos se sustituyen por un hash en la clave (evita colisiones por recorte)
};

const SEG_DIA_MS = 86400000;
const SEG_PARAMETROS_IGNORADOS = /^(utm_[a-z0-9_]+|fbclid|gclid|msclkid|mc_cid|mc_eid|_ga|igshid)$/i;
const SEG_CODIGOS_CONTENIDO = ['sin_titulo', 'h1', 'contenido_minimo', 'error_interno_200'];
const SEG_CODIGOS_ERROR_HTTP = ['error_servidor', 'no_encontrada', 'error_cliente'];

const segLimites = (opciones) => ({ ...LIMITES_SEGUIMIENTO, ...((opciones && opciones.limites) || {}) });
const segCmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const segGravedad = (g) => (typeof g === 'string' && Object.prototype.hasOwnProperty.call(ORDEN_GRAVEDAD, g) ? g : 'info');
const segOrdenGravedad = (g) => ORDEN_GRAVEDAD[segGravedad(g)];
const segPorGravedadYClave = (a, b) => segOrdenGravedad(a.gravedad ?? a.gravedadAnterior) - segOrdenGravedad(b.gravedad ?? b.gravedadAnterior) || segCmp(a.clave, b.clave);
const segFechaMs = (iso) => (typeof iso === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(iso) ? Date.parse(iso) : NaN);
const segEsObjeto = (x) => x !== null && typeof x === 'object' && !Array.isArray(x);
const segCantidad = (inc) => (inc && inc.evidencia && Number.isFinite(inc.evidencia.total) ? inc.evidencia.total : null);

function segHash(texto) {
  let a = 0x811c9dc5;
  let b = 0x9e3779b9;
  const t = String(texto ?? '');
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    a = Math.imul(a ^ c, 0x01000193) >>> 0;
    b = Math.imul(b ^ c, 0x85ebca6b) >>> 0;
    b = (b ^ (b >>> 13)) >>> 0;
  }
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
}

function normalizarDestino(texto) {
  const crudo = String(texto ?? '').trim();
  if (!crudo) return '';
  let ruta;
  let query;
  if (/^https?:\/\//i.test(crudo)) {
    const u = normalizarUrl(crudo, undefined);
    if (!u) return crudo;
    ruta = u.pathname;
    query = String(u.search || '').replace(/^\?/, '');
  } else if (crudo.charAt(0) === '/') {
    const sinFragmento = crudo.split('#')[0];
    const i = sinFragmento.indexOf('?');
    ruta = i >= 0 ? sinFragmento.slice(0, i) : sinFragmento;
    query = i >= 0 ? sinFragmento.slice(i + 1) : '';
  } else {
    return crudo;
  }
  ruta = ruta.replace(/\/{2,}/g, '/');
  if (ruta.length > 1) ruta = ruta.replace(/\/+$/, '');
  if (!ruta) ruta = '/';
  const pares = query.split('&').filter((p) => p && !SEG_PARAMETROS_IGNORADOS.test(p.split('=')[0])).sort(segCmp);
  return pares.length ? `${ruta}?${pares.join('&')}` : ruta;
}

function segClaveDestino(destino, L = LIMITES_SEGUIMIENTO) {
  return destino.length <= L.maxLongitudDestino ? destino : `${destino.slice(0, 60)}~${segHash(destino)}`;
}

function claveSeguimiento(inc, opciones) {
  const L = segLimites(opciones);
  const id = String((inc && inc.id) ?? '');
  const p = id.split(':');
  const area = String((inc && inc.area) ?? p[0] ?? '');
  const codigo = p[1] ?? '';
  let resto = p.slice(2).join(':');
  if (id.length >= 200 && inc && inc.evidencia && typeof inc.evidencia.url === 'string') resto = inc.evidencia.url;
  const base = `${area}:${codigo}`;
  return resto ? `${base}:${segClaveDestino(normalizarDestino(resto), L)}` : base;
}

function segPartesClave(clave) {
  const i = clave.indexOf(':');
  const j = i >= 0 ? clave.indexOf(':', i + 1) : -1;
  return { area: i >= 0 ? clave.slice(0, i) : clave, codigo: i >= 0 ? (j >= 0 ? clave.slice(i + 1, j) : clave.slice(i + 1)) : '', destino: j >= 0 ? clave.slice(j + 1) : '' };
}

function segNormalizarAlcance(al, L) {
  if (!segEsObjeto(al)) return null;
  const lista = (x) => [...new Set((Array.isArray(x) ? x : []).filter((d) => typeof d === 'string' && d).slice(0, 2000).map((d) => segClaveDestino(normalizarDestino(d), L)))].sort(segCmp);
  const cat = segEsObjeto(al.catalogo) ? al.catalogo : {};
  return {
    host: typeof al.host === 'string' && al.host ? al.host.toLowerCase() : null,
    salud: al.salud === true,
    rutas: lista(al.rutas),
    enlaces: lista(al.enlaces),
    fichas: lista(al.fichas),
    contenido: segEsObjeto(al.contenido) ? { rutas: lista(al.contenido.rutas), fichas: lista(al.contenido.fichas) } : null,
    catalogo: { leido: cat.leido === true, completo: cat.completo === true },
  };
}

function segCalidad(inf, lista, alcance, L) {
  const motivos = [];
  const peticiones = Number.isInteger(inf.resumen && inf.resumen.peticiones) ? inf.resumen.peticiones : null;
  const errores = lista.filter((i) => /^(salud|ruta|enlace|ficha):(sin_respuesta|sin_datos)(:|$)/.test(i.id)).length;
  const saludOk = alcance ? alcance.salud === true : !lista.some((i) => /^salud:(sin_datos|sin_respuesta)(:|$)/.test(i.id));
  const respuestas = peticiones === null ? null : peticiones - errores;
  if (peticiones === 0) motivos.push('sin_peticiones');
  else if (respuestas !== null && respuestas <= 0) motivos.push('sin_respuestas');
  else if (peticiones === null && !saludOk) motivos.push('sin_datos_de_salud');
  if (motivos.length) return { estado: 'fallida', motivos };
  if (!saludOk) motivos.push('sin_datos_de_salud');
  if (lista.some((i) => /^catalogo:(feed_parcial|feed_no_disponible)(:|$)/.test(i.id))) motivos.push('catalogo_no_leido_completo');
  if (peticiones && errores / peticiones > L.umbralErroresParcial) motivos.push('muchas_peticiones_sin_respuesta');
  return { estado: motivos.length ? 'parcial' : 'completa', motivos };
}

function resumirInstantanea(informe, opciones) {
  const L = segLimites(opciones);
  const inf = segEsObjeto(informe) ? informe : {};
  const lista = (Array.isArray(inf.incidencias) ? inf.incidencias : []).filter((i) => segEsObjeto(i) && typeof i.id === 'string' && i.ambito !== 'entorno_local');
  const porClave = new Map();
  for (const inc of lista) {
    const clave = claveSeguimiento(inc, opciones);
    const partes = segPartesClave(clave);
    const gravedad = segGravedad(inc.gravedad);
    const cantidad = segCantidad(inc);
    const previo = porClave.get(clave);
    if (!previo) {
      porClave.set(clave, { clave, area: partes.area, codigo: partes.codigo, gravedad, cantidad, ocurrencias: 1 });
    } else {
      previo.ocurrencias += 1;
      if (segOrdenGravedad(gravedad) < segOrdenGravedad(previo.gravedad)) previo.gravedad = gravedad;
      if (cantidad !== null && (previo.cantidad === null || cantidad > previo.cantidad)) previo.cantidad = cantidad;
    }
  }
  const alcance = segNormalizarAlcance(inf.alcance, L);
  const host = typeof (opciones && opciones.host) === 'string' && opciones.host ? opciones.host.toLowerCase() : alcance ? alcance.host : null;
  return {
    esquema: ESQUEMA_SEGUIMIENTO,
    agente: 'auditor-general',
    version: typeof inf.version === 'string' ? inf.version : '',
    entorno: typeof inf.entorno === 'string' ? inf.entorno : '',
    host,
    generadoEn: typeof inf.generadoEn === 'string' ? inf.generadoEn : '',
    calidad: segCalidad(inf, lista, alcance, L),
    alcance,
    incidencias: [...porClave.values()].sort(segPorGravedadYClave),
  };
}

function validarEstado(estado) {
  if (!segEsObjeto(estado) || !Number.isInteger(estado.esquema)) return { ok: false, motivo: 'estado_invalido' };
  if (estado.esquema !== ESQUEMA_SEGUIMIENTO) return { ok: false, motivo: 'esquema_incompatible' };
  if (!segEsObjeto(estado.incidencias) || !segEsObjeto(estado.ultimaInstantanea) || Number.isNaN(segFechaMs(estado.ultimaInstantanea.generadoEn))) return { ok: false, motivo: 'estado_invalido' };
  if (typeof estado.entorno !== 'string' || !Number.isInteger(estado.revision) || estado.revision < 0) return { ok: false, motivo: 'estado_invalido' };
  for (const v of Object.values(estado.incidencias)) {
    if (!segEsObjeto(v) || Number.isNaN(segFechaMs(v.primeraVez)) || Number.isNaN(segFechaMs(v.ultimaVez))) return { ok: false, motivo: 'estado_invalido' };
  }
  return { ok: true, motivo: null };
}

function estadoDesdeInstantanea(inst, opciones) {
  const L = segLimites(opciones);
  const incidencias = {};
  for (const i of [...(inst.incidencias || [])].sort(segPorGravedadYClave).slice(0, L.maxIncidencias)) {
    incidencias[i.clave] = { area: i.area, codigo: i.codigo, gravedad: i.gravedad, cantidad: i.cantidad ?? null, primeraVez: inst.generadoEn, ultimaVez: inst.generadoEn, consecutivas: 1, sinVerificar: 0 };
  }
  return { esquema: ESQUEMA_SEGUIMIENTO, agente: 'auditor-general', entorno: inst.entorno, host: inst.host ?? null, revision: 0, actualizadoEn: inst.generadoEn, ultimaInstantanea: { generadoEn: inst.generadoEn, version: inst.version, calidad: inst.calidad ? inst.calidad.estado : 'completa', huella: segHash(Object.keys(incidencias).sort(segCmp).join('|')) }, incidencias, resueltasRecientes: [] };
}

function segVerificable(clave, actual, conjuntos, erroresHttp) {
  const al = actual.alcance;
  if (!al) return { ok: false, motivo: 'sin_alcance' };
  const { area, codigo, destino } = segPartesClave(clave);
  if (area === 'salud') return al.salud === true ? { ok: true } : { ok: false, motivo: 'salud_no_leida' };
  if (area === 'catalogo') return al.catalogo.completo === true ? { ok: true } : { ok: false, motivo: 'catalogo_no_leido_completo' };
  const conjunto = conjuntos[area];
  if (!conjunto) return { ok: false, motivo: 'area_desconocida' };
  if (!conjunto.has(destino)) return { ok: false, motivo: 'objetivo_no_revisado' };
  if (SEG_CODIGOS_CONTENIDO.includes(codigo)) {
    if (erroresHttp.has(`${area}:${destino}`)) return { ok: false, motivo: 'pagina_con_error' };
    const analizadas = conjuntos.contenido && conjuntos.contenido[area];
    if (conjuntos.contenido && !(analizadas && analizadas.has(destino))) return { ok: false, motivo: 'analisis_incompleto' };
  }
  return { ok: true };
}

const segCambioGravedad = (actual, anterior) => (segOrdenGravedad(actual) < segOrdenGravedad(anterior) ? 'empeora' : segOrdenGravedad(actual) > segOrdenGravedad(anterior) ? 'mejora' : null);

function compararConEstado(estado, actual, opciones) {
  const L = segLimites(opciones);
  const nActuales = actual && Array.isArray(actual.incidencias) ? actual.incidencias.length : 0;
  const vacio = (modo, motivo) => ({
    esquema: ESQUEMA_SEGUIMIENTO,
    modo,
    motivo,
    comparadoCon: null,
    calidad: actual && actual.calidad ? actual.calidad : null,
    resumen: { actuales: nActuales, nuevas: 0, persistentes: 0, resueltas: 0, noVerificadas: 0, reaparecidas: 0, indeterminadas: 0, caducadas: 0 },
    nuevas: [],
    persistentes: [],
    resueltas: [],
    noVerificadas: [],
    reaparecidas: [],
    indeterminadas: [],
    caducadas: [],
  });
  const genMs = segFechaMs(actual && actual.generadoEn);
  if (!actual || actual.esquema !== ESQUEMA_SEGUIMIENTO || !Array.isArray(actual.incidencias) || Number.isNaN(genMs) || !actual.calidad || typeof actual.calidad.estado !== 'string') return vacio('sin_comparar', 'instantanea_invalida');
  if (actual.calidad.estado === 'fallida') return vacio('sin_comparar', 'ejecucion_fallida');
  if (estado === null || estado === undefined) return vacio('linea_base', 'primera_ejecucion');
  const valido = validarEstado(estado);
  if (!valido.ok) return vacio('linea_base', valido.motivo);
  if (estado.entorno !== actual.entorno) return vacio('linea_base', 'entorno_distinto');
  if (estado.host && actual.host && estado.host !== actual.host) return vacio('linea_base', 'host_distinto');
  const prevMs = segFechaMs(estado.ultimaInstantanea.generadoEn);
  if (genMs <= prevMs) return vacio('sin_comparar', 'orden_invalido');
  if ((genMs - prevMs) / SEG_DIA_MS > L.maxAntiguedadDias) return vacio('linea_base', 'anterior_antiguo');

  const salida = vacio('comparacion', null);
  salida.comparadoCon = estado.ultimaInstantanea.generadoEn;
  const al = actual.alcance;
  const conjuntos = al ? { ruta: new Set(al.rutas), enlace: new Set(al.enlaces), ficha: new Set(al.fichas), contenido: al.contenido ? { ruta: new Set(al.contenido.rutas), ficha: new Set(al.contenido.fichas) } : null } : {};
  const estadoRecortado = Boolean(estado.recortado && estado.recortado.omitidas > 0);
  const erroresHttp = new Set(actual.incidencias.filter((i) => (i.area === 'ruta' || i.area === 'ficha') && SEG_CODIGOS_ERROR_HTTP.includes(i.codigo)).map((i) => `${i.area}:${segPartesClave(i.clave).destino}`));
  const recientes = new Map((Array.isArray(estado.resueltasRecientes) ? estado.resueltasRecientes : []).filter((r) => segEsObjeto(r) && typeof r.clave === 'string').map((r) => [r.clave, r]));
  const vistas = new Set();

  for (const i of actual.incidencias) {
    vistas.add(i.clave);
    const p = estado.incidencias[i.clave];
    const comun = { clave: i.clave, area: i.area, codigo: i.codigo, gravedad: i.gravedad, cantidad: i.cantidad ?? null };
    if (p) {
      salida.persistentes.push({ ...comun, gravedadAnterior: p.gravedad, cambioGravedad: segCambioGravedad(i.gravedad, p.gravedad), variacionCantidad: Number.isFinite(i.cantidad) && Number.isFinite(p.cantidad) ? i.cantidad - p.cantidad : null, desde: p.primeraVez, ejecuciones: (p.consecutivas || 1) + 1 });
      continue;
    }
    const r = recientes.get(i.clave);
    if (r && (genMs - segFechaMs(r.resueltaEn)) / SEG_DIA_MS <= L.diasReaparicion) {
      salida.reaparecidas.push({ ...comun, resueltaEn: r.resueltaEn, reapariciones: (r.reapariciones || 0) + 1 });
    } else if (estadoRecortado) {
      salida.indeterminadas.push({ ...comun, motivo: 'estado_recortado' });
    } else {
      salida.nuevas.push(comun);
    }
  }

  for (const [clave, p] of Object.entries(estado.incidencias)) {
    if (vistas.has(clave)) continue;
    const { area, codigo } = segPartesClave(clave);
    const v = segVerificable(clave, actual, conjuntos, erroresHttp);
    const base = { clave, area, codigo, gravedadAnterior: p.gravedad, desde: p.primeraVez };
    if (v.ok) {
      salida.resueltas.push({ ...base, resueltaEn: actual.generadoEn, diasAbierta: Math.max(0, Math.floor((genMs - segFechaMs(p.primeraVez)) / SEG_DIA_MS)), reapariciones: p.reapariciones || 0 });
    } else if ((p.sinVerificar || 0) + 1 > L.maxEjecucionesSinVerificar) {
      salida.caducadas.push({ ...base, motivo: 'sin_verificar_demasiado_tiempo', sinVerificar: (p.sinVerificar || 0) + 1 });
    } else {
      salida.noVerificadas.push({ ...base, motivo: v.motivo, sinVerificar: (p.sinVerificar || 0) + 1 });
    }
  }

  for (const k of ['nuevas', 'persistentes', 'reaparecidas', 'indeterminadas', 'resueltas', 'noVerificadas', 'caducadas']) salida[k].sort(segPorGravedadYClave);
  salida.resumen = { actuales: nActuales, nuevas: salida.nuevas.length, persistentes: salida.persistentes.length, resueltas: salida.resueltas.length, noVerificadas: salida.noVerificadas.length, reaparecidas: salida.reaparecidas.length, indeterminadas: salida.indeterminadas.length, caducadas: salida.caducadas.length };
  return salida;
}

function compararInstantaneas(anterior, actual, opciones) {
  const estado = anterior ? estadoDesdeInstantanea(anterior, opciones) : null;
  return compararConEstado(estado, actual, opciones);
}

function siguienteEstado(estado, actual, comparacion, opciones) {
  const L = segLimites(opciones);
  const revisionBase = estado && Number.isInteger(estado.revision) ? estado.revision : 0;
  const sinCambio = (motivo) => ({ guardar: false, motivo, estado: estado === undefined ? null : estado, revisionBase });
  if (comparacion.modo === 'sin_comparar') return sinCambio(comparacion.motivo);
  if (actual.calidad.estado !== 'completa') return sinCambio('ejecucion_parcial');

  const gen = actual.generadoEn;
  const genMs = segFechaMs(gen);
  const continua = comparacion.modo === 'comparacion';
  const previas = continua ? estado.incidencias : {};
  const recientesPrevias = continua && Array.isArray(estado.resueltasRecientes) ? estado.resueltasRecientes : [];
  const reaparecidas = new Map(comparacion.reaparecidas.map((r) => [r.clave, r]));
  const nuevo = {};

  for (const i of actual.incidencias) {
    const p = previas[i.clave];
    const re = reaparecidas.get(i.clave);
    nuevo[i.clave] = {
      area: i.area,
      codigo: i.codigo,
      gravedad: i.gravedad,
      cantidad: i.cantidad ?? null,
      primeraVez: p ? p.primeraVez : gen,
      ultimaVez: gen,
      consecutivas: p ? (p.consecutivas || 1) + 1 : 1,
      sinVerificar: 0,
      ...(re ? { reapariciones: re.reapariciones } : p && p.reapariciones ? { reapariciones: p.reapariciones } : {}),
    };
  }
  for (const nv of comparacion.noVerificadas) nuevo[nv.clave] = { ...previas[nv.clave], sinVerificar: nv.sinVerificar };

  const resueltas = comparacion.resueltas.map((r) => ({ clave: r.clave, resueltaEn: gen, primeraVez: r.desde, reapariciones: r.reapariciones || 0 }));
  const vigentes = recientesPrevias.filter((r) => segEsObjeto(r) && typeof r.clave === 'string' && !(r.clave in nuevo) && (genMs - segFechaMs(r.resueltaEn)) / SEG_DIA_MS <= L.diasReaparicion);
  const resueltasRecientes = [...resueltas, ...vigentes.filter((r) => !resueltas.some((x) => x.clave === r.clave))].sort((a, b) => segCmp(b.resueltaEn, a.resueltaEn) || segCmp(a.clave, b.clave)).slice(0, L.maxResueltasRecientes);

  let claves = Object.keys(nuevo).sort((a, b) => segOrdenGravedad(nuevo[a].gravedad) - segOrdenGravedad(nuevo[b].gravedad) || segCmp(a, b));
  const total = claves.length;
  if (claves.length > L.maxIncidencias) claves = claves.slice(0, L.maxIncidencias);
  const construir = (lista) => {
    const incidencias = {};
    for (const k of [...lista].sort(segCmp)) incidencias[k] = nuevo[k];
    const e = {
      esquema: ESQUEMA_SEGUIMIENTO,
      agente: 'auditor-general',
      entorno: actual.entorno,
      host: actual.host || (estado && estado.host) || null,
      revision: revisionBase + 1,
      actualizadoEn: gen,
      ultimaInstantanea: { generadoEn: gen, version: actual.version, calidad: actual.calidad.estado, huella: segHash(actual.incidencias.map((i) => i.clave).join('|')), ...(opciones && typeof opciones.idEjecucion === 'string' && opciones.idEjecucion ? { idEjecucion: opciones.idEjecucion.slice(0, 64) } : {}) },
      incidencias,
      resueltasRecientes,
    };
    if (lista.length < total) e.recortado = { conservadas: lista.length, omitidas: total - lista.length };
    return e;
  };
  let resultado = construir(claves);
  while (bytesUtf8(JSON.stringify(resultado)) > L.maxBytesEstado && claves.length > 0) {
    claves = claves.slice(0, Math.max(0, claves.length - Math.max(1, Math.ceil(claves.length / 10))));
    resultado = construir(claves);
  }
  return { guardar: true, motivo: continua ? 'ok' : comparacion.motivo, estado: resultado, revisionBase };
}

function validarEscritura(almacenado, resultado) {
  if (!resultado || resultado.guardar !== true || !resultado.estado) return { ok: false, motivo: 'nada_que_guardar' };
  const revision = almacenado && Number.isInteger(almacenado.revision) ? almacenado.revision : 0;
  if (revision !== resultado.revisionBase) return { ok: false, motivo: 'conflicto_revision', revisionAlmacenada: revision };
  const gAlmacenado = almacenado && almacenado.ultimaInstantanea ? segFechaMs(almacenado.ultimaInstantanea.generadoEn) : NaN;
  if (!Number.isNaN(gAlmacenado) && gAlmacenado >= segFechaMs(resultado.estado.ultimaInstantanea.generadoEn)) return { ok: false, motivo: 'orden_invalido' };
  return { ok: true, motivo: null };
}

function ejecutarSeguimiento(estadoPrevio, informe, opciones) {
  const instantanea = resumirInstantanea(informe, opciones);
  const seguimiento = compararConEstado(estadoPrevio, instantanea, opciones);
  const siguiente = siguienteEstado(estadoPrevio, instantanea, seguimiento, opciones);
  return { instantanea, seguimiento, siguiente };
}

// ── auditor.mjs ──
const VERSION_AUDITOR = '0.2.0';

const incidencia = (area, codigo, gravedad, titulo, detalle, evidencia, accionSugerida, clave = '') => ({
  id: `${area}:${codigo}${clave ? `:${clave}` : ''}`.slice(0, 200),
  gravedad,
  area,
  titulo,
  detalle,
  evidencia: evidencia ?? {},
  accionSugerida,
});

const CLASE_POR_CODIGO = {
  'salud:sin_respuesta': 'disponibilidad', 'salud:http': 'disponibilidad', 'salud:no_json': 'disponibilidad', 'salud:estado': 'disponibilidad', 'salud:sin_volumen': 'integridad_datos',
  'salud:sin_huella': 'configuracion', 'salud:sin_smtp': 'configuracion', 'salud:reinicio_reciente': 'operacion', 'salud:sin_datos': 'disponibilidad',
  'catalogo:feed_no_disponible': 'disponibilidad', 'catalogo:feed_parcial': 'disponibilidad', 'catalogo:vacio': 'integridad_datos', 'catalogo:revision_parcial': 'cobertura',
  'catalogo:ids_duplicados': 'integridad_datos', 'catalogo:sin_precio': 'integridad_datos', 'catalogo:precio_extremo': 'integridad_datos', 'catalogo:precio_anterior_menor': 'integridad_datos',
  'catalogo:descuento_sospechoso': 'honestidad_comercial', 'catalogo:valoracion_por_defecto': 'honestidad_comercial', 'catalogo:imagen_no_segura': 'seguridad', 'catalogo:sin_imagen': 'calidad_datos',
  'catalogo:titulos_repetidos': 'calidad_datos', 'catalogo:sin_categoria': 'calidad_datos', 'catalogo:sin_descripcion': 'calidad_datos', 'catalogo:titulo_largo': 'calidad_datos',
  'catalogo:sin_comercio': 'calidad_datos', 'catalogo:categorias_escasas': 'calidad_datos', 'catalogo:concentracion_comercio': 'calidad_datos',
};
const SOLO_AVISO_LOCAL = new Set(['salud:sin_huella', 'salud:sin_smtp', 'salud:reinicio_reciente', 'catalogo:revision_parcial', 'catalogo:categorias_escasas', 'catalogo:concentracion_comercio']);

function clasificarIncidencia(inc, cfg) {
  const base = inc.id.split(':').slice(0, 2).join(':');
  let clase = CLASE_POR_CODIGO[base];
  if (!clase) clase = inc.area === 'ruta' || inc.area === 'ficha' ? (/^(ruta|ficha):(sin_titulo|h1|contenido_minimo)/.test(inc.id) ? 'seo_contenido' : 'disponibilidad') : inc.area === 'enlace' ? 'enlaces' : 'calidad_datos';
  const aviso = cfg.entorno === 'local' && SOLO_AVISO_LOCAL.has(base);
  return { ...inc, clase, ambito: aviso ? 'entorno_local' : inc.area === 'catalogo' ? 'datos' : 'produccion' };
}

const marcador = (cfg) => ({ id: 'marcador', tipo: 'marcador', marcador: true, url: `${cfg.baseUrl.replace(/\/$/, '')}/api/health` });


function planificarRutas(cfg) {
  const objetivos = [];
  const omitidos = [];
  const base = cfg.baseUrl.replace(/\/$/, '');
  const salud = evaluarUrl(`${base}/api/health`, 'salud', cfg);
  if (salud.ok) objetivos.push({ id: 'salud', tipo: 'salud', url: salud.url, etiqueta: '/api/health' });
  else omitidos.push({ etiqueta: '/api/health', motivo: salud.motivo });
  for (const r of cfg.rutas) {
    const e = evaluarUrl(`${base}${r}`, 'ruta', cfg);
    if (e.ok) objetivos.push({ id: `ruta:${r}`, tipo: 'ruta', url: e.url, etiqueta: r });
    else omitidos.push({ etiqueta: r, motivo: e.motivo });
  }
  return { objetivos, omitidos };
}
function crearObjetivosRutas(cfg) {
  const { objetivos } = planificarRutas(cfg);
  return objetivos.length ? objetivos : [marcador(cfg)];
}

function emparejar(objetivos, respuestas) {
  const out = [];
  for (let i = 0; i < objetivos.length; i++) {
    const t = objetivos[i];
    const r = respuestas[i] ?? {};
    if (!t || t.marcador) continue;
    if (r.statusCode === undefined && !r.error) continue;
    out.push({ t, r });
  }
  return out;
}

const cuerpoTexto = (r) => (typeof r.data === 'string' ? r.data : typeof r.body === 'string' ? r.body : '');
const errorTexto = (r) => (r.error ? recortar(typeof r.error === 'string' ? r.error : r.error.message ?? JSON.stringify(r.error), 200) : '');
const esHtml = (r) => /html/i.test(String((r.headers ?? {})['content-type'] ?? '')) || /<html|<!doctype/i.test(cuerpoTexto(r).slice(0, 400));

function extraerEnlaces(html, baseUrl) {
  const out = [];
  const limpio = String(html ?? '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<!--[\s\S]*?-->/g, ' ');
  for (const m of limpio.matchAll(/<a\s[^>]*?href\s*=\s*(?:"([^"]*)"|'([^']*)')/gi)) {
    const crudo = (m[1] ?? m[2] ?? '').replace(/&amp;/g, '&').trim();
    if (!crudo || crudo.includes('${') || crudo.includes('{{') || crudo.startsWith('#') || /^(mailto:|tel:|javascript:|data:)/i.test(crudo)) continue;
    const u = normalizarUrl(crudo, baseUrl);
    if (u) out.push(u.toString());
  }
  return out;
}

function descubrirEnlaces(objetivos, respuestas, cfg) {
  const yaPedidos = new Set(objetivos.filter((t) => !t.marcador).map((t) => t.url));
  const vistos = new Map();
  for (const { t, r } of emparejar(objetivos, respuestas)) {
    if (t.tipo !== 'ruta' || r.statusCode !== 200 || !esHtml(r)) continue;
    for (const href of extraerEnlaces(cuerpoTexto(r), t.url)) {
      const e = evaluarUrl(href, 'enlace', cfg);
      if (!e.ok || yaPedidos.has(e.url) || vistos.has(e.url)) continue;
      vistos.set(e.url, t.etiqueta);
    }
  }
  return [...vistos.entries()].sort((a, b) => a[0].localeCompare(b[0]));
}

function crearObjetivosEnlaces(objetivos, respuestas, cfg) {
  const lista = descubrirEnlaces(objetivos, respuestas, cfg).slice(0, cfg.maxEnlaces);
  const objetivosEnlaces = lista.map(([url, origen]) => ({ id: `enlace:${url}`, tipo: 'enlace', url, origen }));
  return objetivosEnlaces.length ? objetivosEnlaces : [marcador(cfg)];
}

const urlCatalogo = (cfg, pagina) => evaluarUrl(`${cfg.baseUrl.replace(/\/$/, '')}${RUTA_CATALOGO_AUTOMATIZACION}?limit=${cfg.limitePorPagina}&page=${pagina}`, 'catalogo', cfg);

function crearObjetivosCatalogo(cfg) {
  const out = [];
  if (cfg.modo === 'completo' && cfg.maxPaginasCatalogo >= 1) {
    const e = urlCatalogo(cfg, 1);
    if (e.ok) out.push({ id: 'catalogo:1', tipo: 'catalogo', url: e.url, pagina: 1 });
  }
  return out.length ? out : [marcador(cfg)];
}

function crearObjetivosCatalogoResto(objetivos, respuestas, cfg) {
  const primera = leerCatalogo(objetivos, respuestas);
  const out = [];
  if (cfg.modo === 'completo' && Number.isInteger(primera.totalPaginas)) {
    for (let p = 2; p <= Math.min(primera.totalPaginas, cfg.maxPaginasCatalogo); p++) {
      const e = urlCatalogo(cfg, p);
      if (e.ok) out.push({ id: `catalogo:${p}`, tipo: 'catalogo', url: e.url, pagina: p });
    }
  }
  return out.length ? out : [marcador(cfg)];
}

function leerCatalogo(objetivos, respuestas) {
  const productos = [];
  const errores = [];
  let total = null;
  let totalPaginas = null;
  for (const { t, r } of emparejar(objetivos, respuestas)) {
    if (t.tipo !== 'catalogo') continue;
    if (r.error || r.statusCode !== 200) {
      errores.push(`página ${t.pagina}: ${r.error ? errorTexto(r) : `HTTP ${r.statusCode}`}`);
      continue;
    }
    try {
      const j = JSON.parse(cuerpoTexto(r));
      if (!Array.isArray(j.products)) throw new Error('sin lista de productos');
      productos.push(...j.products);
      if (Number.isInteger(j.total)) total = j.total;
      if (Number.isInteger(j.totalPages)) totalPaginas = j.totalPages;
    } catch (e) {
      errores.push(`página ${t.pagina}: respuesta no válida (${recortar(e.message, 80)})`);
    }
  }
  return { productos, total, totalPaginas, errores };
}

function crearObjetivosFichas(productos, cfg) {
  const base = cfg.baseUrl.replace(/\/$/, '');
  const out = [];
  if (cfg.modo === 'completo') {
    const ids = [...new Set(productos.map((p) => String(p.id ?? '')).filter(Boolean))].sort().slice(0, cfg.maxFichas);
    for (const id of ids) {
      const e = evaluarUrl(`${base}/producto/${id}`, 'ficha', cfg);
      if (e.ok) out.push({ id: `ficha:${id}`, tipo: 'ficha', url: e.url, productoId: id });
    }
  }
  return out.length ? out : [marcador(cfg)];
}


function analizarSalud(objetivos, respuestas) {
  const inc = [];
  const par = emparejar(objetivos, respuestas).find((x) => x.t.tipo === 'salud');
  let datos = null;
  if (!par) {
    inc.push(incidencia('salud', 'sin_datos', 'critica', 'No se pudo comprobar la salud del servidor', 'No hay respuesta de /api/health.', {}, 'Comprobar que el servidor está en marcha y que el agente llega a él.'));
    return { incidencias: inc, datos };
  }
  const { r } = par;
  if (r.error) inc.push(incidencia('salud', 'sin_respuesta', 'critica', 'El servidor no responde', errorTexto(r), {}, 'Comprobar el contenedor y la red.'));
  else if (r.statusCode !== 200) inc.push(incidencia('salud', 'http', 'critica', `/api/health devuelve HTTP ${r.statusCode}`, 'El healthcheck no es correcto.', { statusCode: r.statusCode }, 'Revisar los registros del servicio.'));
  else {
    try {
      datos = JSON.parse(cuerpoTexto(r));
    } catch {
      inc.push(incidencia('salud', 'no_json', 'alta', '/api/health no devuelve JSON válido', 'La respuesta no se puede interpretar.', {}, 'Revisar el servicio.'));
    }
  }
  if (datos) {
    if (datos.status !== 'ok') inc.push(incidencia('salud', 'estado', 'critica', `Estado de salud: ${datos.status}`, 'El servicio no declara «ok».', { status: datos.status }, 'Revisar registros.'));
    if (datos.dataDirExists === false) inc.push(incidencia('salud', 'sin_volumen', 'critica', 'No existe el directorio de datos', 'El volumen persistente no está disponible.', {}, 'Revisar el volumen del servicio.'));
    if (!datos.sourceHash) inc.push(incidencia('salud', 'sin_huella', 'media', 'El despliegue no declara su huella de código (sourceHash)', 'No se puede comprobar qué código se está ejecutando.', {}, 'Revisar el build.'));
    if (Number.isFinite(datos.uptimeSeconds) && datos.uptimeSeconds < 300) inc.push(incidencia('salud', 'reinicio_reciente', 'info', 'El servicio se reinició hace menos de 5 minutos', `Tiempo de actividad: ${datos.uptimeSeconds} s.`, { uptimeSeconds: datos.uptimeSeconds }, 'Comprobar si fue un despliegue previsto.'));
    if (datos.env && datos.env.smtp === false) inc.push(incidencia('salud', 'sin_smtp', 'baja', 'El correo (SMTP) no está configurado', 'Los correos de la plataforma no se enviarán por SMTP.', {}, 'Revisar la configuración si se esperan correos.'));
  }
  return { incidencias: inc, datos };
}

function analizarPagina(par, area) {
  const { t, r } = par;
  const inc = [];
  const ev = { url: t.url, statusCode: r.statusCode ?? null };
  const clave = t.etiqueta ?? t.productoId ?? t.url;
  if (r.error) {
    inc.push(incidencia(area, 'sin_respuesta', area === 'ruta' ? 'critica' : 'alta', `Sin respuesta: ${clave}`, errorTexto(r), ev, 'Comprobar la ruta y el servidor.', clave));
    return inc;
  }
  if (r.statusCode >= 500) inc.push(incidencia(area, 'error_servidor', 'critica', `Error ${r.statusCode} en ${clave}`, 'El servidor devuelve un error.', ev, 'Revisar registros.', clave));
  else if (r.statusCode === 404 || r.statusCode === 410) inc.push(incidencia(area, 'no_encontrada', 'alta', `No existe: ${clave}`, `HTTP ${r.statusCode}.`, ev, 'Corregir el enlace o restaurar la página.', clave));
  else if (r.statusCode >= 400) inc.push(incidencia(area, 'error_cliente', 'media', `HTTP ${r.statusCode} en ${clave}`, 'La página no es accesible para un visitante anónimo.', ev, 'Revisar si es esperado.', clave));
  else if (r.statusCode === 200) {
    const cuerpo = cuerpoTexto(r);
    if (/internal server error/i.test(cuerpo)) inc.push(incidencia(area, 'error_interno_200', 'critica', `Error interno oculto tras un 200 en ${clave}`, 'La página devuelve 200 pero contiene «Internal server error».', ev, 'Revisar registros y el componente que falla.', clave));
    if (esHtml(r)) {
      if (!/<title>[^<]{2,}<\/title>/i.test(cuerpo)) inc.push(incidencia(area, 'sin_titulo', 'media', `Sin <title> en ${clave}`, 'Falta el título de la página (SEO).', ev, 'Añadir título.', clave));
      const h1 = (cuerpo.match(/<h1[\s>]/gi) ?? []).length;
      if (h1 !== 1) inc.push(incidencia(area, 'h1', 'baja', `${h1 === 0 ? 'Sin' : 'Varios'} <h1> en ${clave}`, `Hay ${h1} elementos h1.`, { ...ev, h1 }, 'Dejar un único h1.', clave));
      if (cuerpo.length < 2000) inc.push(incidencia(area, 'contenido_minimo', 'media', `Contenido muy corto en ${clave}`, `Sólo ${cuerpo.length} caracteres.`, { ...ev, caracteres: cuerpo.length }, 'Comprobar que la página se genera completa.', clave));
    }
  }
  return inc;
}

function analizarRutas(objetivos, respuestas) {
  const inc = [];
  let revisadas = 0;
  for (const par of emparejar(objetivos, respuestas)) {
    if (par.t.tipo !== 'ruta') continue;
    revisadas++;
    inc.push(...analizarPagina(par, 'ruta'));
  }
  return { incidencias: inc, revisadas };
}

function analizarEnlaces(objetivos, respuestas) {
  const inc = [];
  let revisados = 0;
  for (const { t, r } of emparejar(objetivos, respuestas)) {
    if (t.tipo !== 'enlace') continue;
    revisados++;
    const ev = { url: t.url, origen: t.origen, statusCode: r.statusCode ?? null };
    if (r.error) inc.push(incidencia('enlace', 'sin_respuesta', 'media', `Enlace sin respuesta: ${t.url}`, errorTexto(r), ev, 'Comprobar el destino.', t.url));
    else if (r.statusCode >= 400) inc.push(incidencia('enlace', 'roto', 'alta', `Enlace interno roto: ${t.url}`, `HTTP ${r.statusCode}; aparece en ${t.origen}.`, ev, 'Corregir o retirar el enlace.', t.url));
  }
  return { incidencias: inc, revisados };
}

function analizarFichas(objetivos, respuestas) {
  const inc = [];
  let revisadas = 0;
  for (const par of emparejar(objetivos, respuestas)) {
    if (par.t.tipo !== 'ficha') continue;
    revisadas++;
    inc.push(...analizarPagina(par, 'ficha'));
  }
  return { incidencias: inc, revisadas };
}

const imagenAceptable = (u) => typeof u === 'string' && (/^https:\/\//i.test(u) || /^\/[^/]/.test(u));

function analizarCatalogo(catalogo, cfg, ahoraIso) {
  const inc = [];
  const { productos, total, errores } = catalogo;
  const um = cfg.umbrales ?? {};
  const grupo = (codigo, gravedad, titulo, detalle, ids, accion) => {
    if (!ids.length) return;
    inc.push(incidencia('catalogo', codigo, gravedad, `${titulo} (${ids.length})`, detalle, { total: ids.length, ejemplos: ids.slice(0, 10) }, accion));
  };
  if (errores.length && !productos.length) {
    inc.push(incidencia('catalogo', 'feed_no_disponible', 'alta', 'No se pudo leer el catálogo', errores.join(' · '), { errores }, 'Comprobar el token de lectura de la instancia y la URL.'));
    return inc;
  }
  if (errores.length) inc.push(incidencia('catalogo', 'feed_parcial', 'media', 'Algunas páginas del catálogo no se pudieron leer', errores.join(' · '), { errores }, 'Repetir la ejecución y revisar el servicio.'));
  if (!productos.length) {
    inc.push(incidencia('catalogo', 'vacio', 'alta', 'El catálogo está vacío', 'El feed no devuelve productos.', { total }, 'Comprobar el volumen de datos.'));
    return inc;
  }
  if (Number.isInteger(total) && total > productos.length) inc.push(incidencia('catalogo', 'revision_parcial', 'info', `Se revisaron ${productos.length} de ${total} productos`, 'El límite de páginas del agente impide revisar todo el catálogo.', { revisados: productos.length, total }, 'Subir maxPaginasCatalogo si se desea una revisión completa.'));

  const porId = new Map();
  const dup = [];
  for (const p of productos) {
    const id = String(p.id ?? '');
    if (porId.has(id)) dup.push(id);
    porId.set(id, p);
  }
  grupo('ids_duplicados', 'alta', 'Identificadores repetidos', 'Dos productos comparten identificador.', [...new Set(dup)], 'Revisar el origen de la importación.');

  const porTitulo = new Map();
  for (const p of productos) {
    const k = plegar(p.title);
    if (k.length >= 12) porTitulo.set(k, [...(porTitulo.get(k) ?? []), String(p.id)]);
  }
  const titulosRepetidos = [...porTitulo.values()].filter((v) => v.length > 1).map((v) => v.slice(0, 3).join(' = '));
  grupo('titulos_repetidos', 'media', 'Títulos idénticos en productos distintos', 'Posibles duplicados (mismo título normalizado).', titulosRepetidos, 'Revisar si es el mismo anuncio con otro vendedor o un duplicado.');

  const idsDe = (fn) => productos.filter(fn).map((p) => String(p.id));
  const precio = (p) => Number(p.price);
  grupo('sin_precio', 'alta', 'Productos sin precio utilizable', 'Precio ausente, cero o negativo.', idsDe((p) => !(precio(p) > 0)), 'Retirar o corregir la ficha.');
  grupo('precio_extremo', 'media', 'Precios extremadamente altos', 'Precio superior a 100.000 €.', idsDe((p) => precio(p) > 100000), 'Comprobar el dato de origen.');
  grupo('precio_anterior_menor', 'media', 'Precio anterior inferior al actual', 'El precio anterior declarado es menor que el actual: el descuento no tiene sentido.', idsDe((p) => precioAnteriorDeclarado(p) !== null && precioAnteriorDeclarado(p) < precio(p)), 'Revisar el precio anterior.');
  grupo('descuento_sospechoso', 'media', 'Descuentos declarados superiores al 80 %', 'Precio anterior más de 5 veces el actual (dato declarado, no verificado).', idsDe((p) => precio(p) > 0 && precioAnteriorDeclarado(p) !== null && precioAnteriorDeclarado(p) > precio(p) * 5), 'No mostrar como descuento sin verificación.');
  grupo('sin_imagen', 'media', 'Productos sin imagen', 'Falta la imagen principal.', idsDe((p) => !p.image), 'Añadir imagen.');
  grupo('imagen_no_segura', 'media', 'Imágenes con dirección no admisible', 'La imagen no es https ni una ruta propia.', idsDe((p) => p.image && !imagenAceptable(p.image)), 'Corregir la URL de la imagen.');
  grupo('sin_categoria', 'media', 'Productos sin categoría', 'Falta la categoría.', idsDe((p) => !String(p.category ?? '').trim()), 'Asignar categoría.');
  grupo('sin_descripcion', 'baja', 'Descripción ausente o muy corta', 'Menos de 40 caracteres.', idsDe((p) => longitudDescripcion(p) < 40), 'Completar la ficha.');
  grupo('titulo_largo', 'baja', 'Títulos de más de 120 caracteres', 'Títulos difíciles de leer.', idsDe((p) => String(p.title ?? '').length > 120), 'Acortar el título.');
  grupo('sin_comercio', 'baja', 'Productos sin comercio', 'Falta el nombre del comercio.', idsDe((p) => !String(p.merchant ?? '').trim()), 'Completar el comercio.');
  grupo('valoracion_por_defecto', 'info', 'Valoración «4,8 / 100 reseñas» (valor por defecto)', 'No es una valoración real; no debe presentarse como tal.', idsDe((p) => p.ratingFlag === 'por_defecto' || (Number(p.rating) === 4.8 && Number(p.reviewsCount) === 100)), 'Ocultar o sustituir por dato real.');

  const porCat = new Map();
  for (const p of productos) {
    const c = String(p.category ?? '').trim();
    if (c) porCat.set(c, (porCat.get(c) ?? 0) + 1);
  }
  const escasas = [...porCat.entries()].filter(([, n]) => n < (um.minProductosPorCategoria ?? 3)).map(([c, n]) => `${c} (${n})`).sort();
  grupo('categorias_escasas', 'baja', 'Categorías con muy pocos productos', `Menos de ${um.minProductosPorCategoria ?? 3} productos.`, escasas, 'Ampliar o fusionar la categoría.');

  const porComercio = new Map();
  for (const p of productos) porComercio.set(String(p.merchant ?? '—'), (porComercio.get(String(p.merchant ?? '—')) ?? 0) + 1);
  const [topComercio, topN] = [...porComercio.entries()].sort((a, b) => b[1] - a[1])[0] ?? ['—', 0];
  if (productos.length >= 10 && topN / productos.length > (um.maxConcentracionComercio ?? 0.8)) {
    inc.push(incidencia('catalogo', 'concentracion_comercio', 'baja', `El ${Math.round((topN / productos.length) * 100)} % del catálogo es de ${topComercio}`, 'Dependencia de un único comercio.', { comercio: topComercio, productos: topN, total: productos.length }, 'Diversificar fuentes.'));
  }
  void ahoraIso;
  void diasEntre;
  void fechaValida;
  return inc;
}


const LIMITES_ESCENARIO = [10, 20, 40];

const tamanoJson = (x) => { try { return bytesUtf8(JSON.stringify(x)); } catch (e) { return 0; } };

const familiaDeUrl = (url) => { const u = normalizarUrl(url, undefined); const seg = u ? u.pathname.split('/').filter(Boolean)[0] : ''; return seg || '/'; };

function formatearBytes(n) {
  const v = Number(n) || 0;
  if (v < 1024) return `${v} B`;
  if (v < 1048576) return `${(v / 1024).toFixed(1).replace('.', ',')} KB`;
  return `${(v / 1048576).toFixed(2).replace('.', ',')} MB`;
}

function calcularConsumo(entrada) {
  const { cfg, objetivosRutas = [], respuestasRutas = [], objetivosEnlaces = [], respuestasEnlaces = [], objetivosCatalogo = [], respuestasCatalogo = [], objetivosFichas = [], respuestasFichas = [], tamanoInforme = 0 } = entrada;
  const grupos = [[objetivosRutas, respuestasRutas], [objetivosEnlaces, respuestasEnlaces], [objetivosCatalogo, respuestasCatalogo], [objetivosFichas, respuestasFichas]];
  const paginas = [];
  for (const [objetivos, respuestas] of grupos) {
    for (const { t, r } of emparejar(objetivos, respuestas)) {
      paginas.push({ tipo: t.tipo, destino: t.url, bytes: bytesUtf8(cuerpoTexto(r)), serializado: tamanoJson(r), estado: r.error ? 'error' : r.statusCode });
    }
  }
  const sobrecarga = grupos.reduce((n, [o]) => n + tamanoJson(o), 0) + tamanoInforme;
  const suma = (lista, k) => lista.reduce((n, p) => n + p[k], 0);
  const porTipo = {};
  for (const p of paginas) {
    porTipo[p.tipo] = porTipo[p.tipo] ?? { peticiones: 0, bytes: 0 };
    porTipo[p.tipo].peticiones++;
    porTipo[p.tipo].bytes += p.bytes;
  }
  const masPesadas = [...paginas].sort((a, b) => b.bytes - a.bytes || a.destino.localeCompare(b.destino)).slice(0, 5).map((p) => ({ tipo: p.tipo, destino: p.destino, bytes: p.bytes, estado: p.estado }));

  const descubiertos = descubrirEnlaces(objetivosRutas, respuestasRutas, cfg);
  const enlaces = paginas.filter((p) => p.tipo === 'enlace'); // en el orden en que se pidieron (alfabético)
  const fijas = paginas.filter((p) => p.tipo !== 'enlace');
  const familiasTodas = new Set(descubiertos.map(([u]) => familiaDeUrl(u)));
  const escenarios = LIMITES_ESCENARIO.map((limite) => {
    const n = Math.min(limite, descubiertos.length);
    const calculable = n <= enlaces.length;
    const e = { maxEnlaces: limite, calculable, enlaces: n };
    if (!calculable) return e;
    const subconjunto = enlaces.slice(0, n);
    const todas = [...fijas, ...subconjunto];
    return { ...e, peticiones: todas.length, bytesRecibidos: suma(todas, 'bytes'), bytesHistorialEstimado: suma(todas, 'serializado') + sobrecarga, familiasCubiertas: new Set(subconjunto.map((p) => familiaDeUrl(p.destino))).size, familiasDescubiertas: familiasTodas.size };
  });

  return {
    peticiones: paginas.length,
    medido: {
      bytesRecibidos: suma(paginas, 'bytes'),
      porTipo,
      paginasMasPesadas: masPesadas,
      nota: 'Medido: bytes UTF-8 del cuerpo de cada respuesta, ya descomprimida. Lo que viajó por la red puede ser menor.',
    },
    estimado: {
      esEstimacion: true,
      bytesHistorial: suma(paginas, 'serializado') + sobrecarga,
      metodo: 'ESTIMACIÓN, no medición: suma del tamaño JSON de la salida de los nodos HTTP, de las listas de objetivos y del informe. n8n no publica lo que guarda de verdad; contrástese con el tamaño real de la ejecución.',
    },
    presupuesto: { maxEnlaces: cfg.maxEnlaces, enlacesDescubiertos: descubiertos.length, enlacesPedidos: enlaces.length, enlacesOmitidosPorTope: Math.max(0, descubiertos.length - enlaces.length) },
    escenarios,
  };
}


function calcularAlcance(entrada, datosSalud, catalogo) {
  const { cfg, objetivosRutas = [], respuestasRutas = [], objetivosEnlaces = [], respuestasEnlaces = [], objetivosFichas = [], respuestasFichas = [] } = entrada;
  const base = normalizarUrl(cfg.baseUrl, undefined);
  const CLAVE = { ruta: 'rutas', enlace: 'enlaces', ficha: 'fichas' };
  const alcance = { host: base ? base.host : null, salud: Boolean(datosSalud), rutas: [], enlaces: [], fichas: [], contenido: { rutas: [], fichas: [] }, catalogo: { leido: false, completo: false }, sinRespuesta: [], incompletas: [] };
  let solicitadas = 0;
  let respondieron = 0;
  let correctas = 0;
  for (const [objetivos, respuestas] of [[objetivosRutas, respuestasRutas], [objetivosEnlaces, respuestasEnlaces], [objetivosFichas, respuestasFichas]]) {
    objetivos.forEach((t, i) => {
      if (!t || t.marcador || !CLAVE[t.tipo]) return;
      const r = respuestas[i] ?? {};
      const destino = t.tipo === 'ruta' ? t.etiqueta : t.tipo === 'ficha' ? t.productoId : t.url;
      solicitadas++;
      if (r.error || typeof r.statusCode !== 'number') {
        alcance.sinRespuesta.push({ tipo: t.tipo, destino, motivo: r.error ? (/timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT|tiempo/i.test(errorTexto(r)) ? 'tiempo_agotado' : 'error_de_red') : 'sin_datos' });
        return;
      }
      respondieron++;
      alcance[CLAVE[t.tipo]].push(destino);
      if (r.statusCode >= 200 && r.statusCode < 300) correctas++;
      if (t.tipo === 'enlace') return; // de un enlace sólo importa su estado HTTP
      if (r.statusCode === 200) {
        if (!esHtml(r)) alcance.incompletas.push({ tipo: t.tipo, destino, motivo: 'respuesta_no_html' });
        else if (!cuerpoTexto(r).trim()) alcance.incompletas.push({ tipo: t.tipo, destino, motivo: 'cuerpo_vacio' });
        else alcance.contenido[CLAVE[t.tipo]].push(destino);
      } else {
        alcance.incompletas.push({ tipo: t.tipo, destino, motivo: r.statusCode >= 400 ? 'error_http' : r.statusCode >= 300 ? 'redireccion' : 'estado_inesperado' });
      }
    });
  }
  const leido = catalogo.productos.length > 0;
  alcance.catalogo = { leido, completo: leido && !catalogo.errores.length && (!Number.isInteger(catalogo.total) || catalogo.productos.length >= catalogo.total) };
  const pedidosEnlaces = objetivosEnlaces.filter((t) => t && !t.marcador).length;
  const noVisitados = Math.max(0, descubrirEnlaces(objetivosRutas, respuestasRutas, cfg).length - pedidosEnlaces);
  alcance.resumen = { solicitadas, respondieron, correctas, sinRespuesta: alcance.sinRespuesta.length, incompletas: alcance.incompletas.length, noVisitados };
  return alcance;
}


const longitudDescripcion = (p) => (Number.isFinite(Number(p.descriptionLength)) ? Number(p.descriptionLength) : String(p.description ?? '').trim().length);

const ETIQUETA_GRAVEDAD = { critica: 'Crítica', alta: 'Alta', media: 'Media', baja: 'Baja', info: 'Información' };

function markdownConsumo(c) {
  const l = ['## Consumo'];
  l.push(`- **Medido:** ${c.peticiones} peticiones · ${formatearBytes(c.medido.bytesRecibidos)} de cuerpo recibido (descomprimido; por la red puede ser menos).`);
  if (c.medido.paginasMasPesadas.length) l.push(`- **Páginas más pesadas:** ${c.medido.paginasMasPesadas.map((p) => `${p.destino} (${formatearBytes(p.bytes)})`).join('; ')}`);
  l.push(`- **Estimado (NO medido):** ≈ ${formatearBytes(c.estimado.bytesHistorial)} en el historial de n8n por ejecución. Es una estimación del tamaño JSON de las salidas; contrastar con el tamaño real de la ejecución.`);
  const p = c.presupuesto;
  l.push(`- **Enlaces internos:** ${p.enlacesPedidos} pedidos de ${p.enlacesDescubiertos} descubiertos (tope ${p.maxEnlaces}${p.enlacesOmitidosPorTope ? `; ${p.enlacesOmitidosPorTope} omitidos por el tope` : ''}).`);
  for (const e of c.escenarios) l.push(e.calculable ? `  - Con tope ${e.maxEnlaces}: ${e.peticiones} peticiones · ${formatearBytes(e.bytesRecibidos)} recibidos · ≈ ${formatearBytes(e.bytesHistorialEstimado)} estimados en el historial · ${e.familiasCubiertas}/${e.familiasDescubiertas} secciones del sitio cubiertas` : `  - Con tope ${e.maxEnlaces}: no calculable con esta ejecución (se pidieron menos enlaces que ese tope)`);
  l.push('');
  return l;
}

const MOTIVOS_SEGUIMIENTO = {
  primera_ejecucion: 'primera ejecución: todavía no hay una auditoría anterior',
  estado_invalido: 'el estado anterior no es válido',
  esquema_incompatible: 'el estado anterior tiene un formato no compatible',
  entorno_distinto: 'el estado anterior es de otro entorno',
  host_distinto: 'el estado anterior es de otro sitio',
  anterior_antiguo: 'la auditoría anterior es demasiado antigua para compararla',
  ejecucion_fallida: 'esta ejecución no obtuvo respuestas suficientes: no se compara ni se guarda',
  orden_invalido: 'la fecha de esta auditoría no es posterior a la anterior',
  instantanea_invalida: 'la auditoría no se pudo resumir',
  sin_alcance: 'el informe no declara qué se revisó',
  objetivo_no_revisado: 'no se visitó o no respondió en esta ejecución',
  salud_no_leida: 'no se pudo leer la salud',
  catalogo_no_leido_completo: 'el catálogo no se leyó completo',
  pagina_con_error: 'la página responde con error',
  analisis_incompleto: 'la página respondió pero su contenido no se pudo analizar',
  area_desconocida: 'área sin comprobación definida',
  sin_verificar_demasiado_tiempo: 'lleva demasiadas ejecuciones sin poder verificarse',
  estado_recortado: 'el estado anterior estaba recortado: no se puede demostrar que fuera nueva',
};

function markdownSeguimiento(s) {
  const l = ['## Seguimiento'];
  const fecha = (iso) => String(iso).slice(0, 16).replace('T', ' ');
  const motivo = (m) => MOTIVOS_SEGUIMIENTO[m] ?? m;
  if (s.modo === 'linea_base') {
    l.push(`**Línea base** — ${motivo(s.motivo)}. Esta auditoría pasa a ser la referencia y **no** se clasifica ninguna incidencia como nueva (${s.resumen.actuales} incidencias actuales).`);
    if (s.origenReferencia === 'ninguna') l.push('_No se proporcionó estado anterior: el almacenamiento del estado llega en una entrega posterior._');
  } else if (s.modo === 'sin_comparar') {
    l.push(`**Sin comparar** — ${motivo(s.motivo)}.`);
  } else {
    const r = s.resumen;
    l.push(`Comparado con la auditoría del ${fecha(s.comparadoCon)} UTC. **Nuevas:** ${r.nuevas} · **Persistentes:** ${r.persistentes} · **Resueltas:** ${r.resueltas} · **No verificadas:** ${r.noVerificadas} · **Reaparecidas:** ${r.reaparecidas}` + (r.indeterminadas ? ` · **Indeterminadas:** ${r.indeterminadas}` : '') + (r.caducadas ? ` · **Caducadas:** ${r.caducadas}` : ''));
    const bloque = (titulo, lista, texto) => {
      if (!lista || !lista.length) return;
      l.push(`### ${titulo} (${lista.length})`);
      for (const x of lista.slice(0, 15)) l.push(`- \`${x.clave}\`${texto(x)}`);
      if (lista.length > 15) l.push(`- … y ${lista.length - 15} más (ver JSON).`);
    };
    bloque('Nuevas', s.nuevas, (x) => ` — ${x.gravedad}`);
    bloque('Reaparecidas', s.reaparecidas, (x) => ` — ${x.gravedad}; resuelta el ${fecha(x.resueltaEn)}`);
    bloque('Persistentes', s.persistentes, (x) => ` — ${x.gravedad}${x.cambioGravedad ? ` (${x.cambioGravedad === 'empeora' ? 'empeora' : 'mejora'}, antes ${x.gravedadAnterior})` : ''}; ${x.ejecuciones} ejecuciones seguidas, desde ${fecha(x.desde)}`);
    bloque('Resueltas', s.resueltas, (x) => ` — estaba ${x.gravedadAnterior}; abierta ${x.diasAbierta} día(s); su destino se revisó en esta ejecución`);
    bloque('No verificadas (no se pueden dar por resueltas)', s.noVerificadas, (x) => ` — ${motivo(x.motivo)}`);
    bloque('Indeterminadas', s.indeterminadas, (x) => ` — ${x.gravedad}; ${motivo(x.motivo)}`);
    bloque('Caducadas', s.caducadas, (x) => ` — ${motivo(x.motivo)}`);
  }
  l.push('');
  return l;
}

function informeMarkdown(informe) {
  const l = [];
  l.push(`# Auditor General — ${informe.entorno} (${informe.generadoEn.slice(0, 16).replace('T', ' ')} UTC)`);
  l.push('');
  l.push(`**Estado:** ${informe.resumen.estado.toUpperCase()} · **Sólo lectura** · versión ${informe.version} · modo ${informe.modo}`);
  const c = informe.resumen.incidencias;
  l.push(`**Incidencias:** crítica ${c.critica} · alta ${c.alta} · media ${c.media} · baja ${c.baja} · info ${c.info}` + (informe.avisosEntorno?.length ? ` · **avisos del entorno local:** ${informe.avisosEntorno.length} (no cuentan)` : ''));
  l.push(`**Peticiones realizadas:** ${informe.resumen.peticiones} (rutas ${informe.resumen.rutasRevisadas}, enlaces ${informe.resumen.enlacesRevisados}, fichas ${informe.resumen.fichasRevisadas}, páginas de catálogo ${informe.resumen.paginasCatalogo})`);
  l.push('');
  for (const g of ['critica', 'alta', 'media', 'baja', 'info']) {
    const lista = informe.incidencias.filter((i) => i.gravedad === g);
    if (!lista.length) continue;
    l.push(`## ${ETIQUETA_GRAVEDAD[g]} (${lista.length})`);
    for (const i of lista.slice(0, 30)) l.push(`- **${i.titulo}** — ${i.detalle} _[${i.clase}] Acción: ${i.accionSugerida}_`);
    if (lista.length > 30) l.push(`- … y ${lista.length - 30} más (ver JSON).`);
    l.push('');
  }
  if (informe.avisosEntorno?.length) {
    l.push(`## Avisos del entorno local (${informe.avisosEntorno.length}) — no son incidencias del sitio real`);
    for (const i of informe.avisosEntorno) l.push(`- ${i.titulo} — ${i.detalle}`);
    l.push('');
  }
  if (!informe.incidencias.length) l.push('Sin incidencias.\n');
  if (informe.seguimiento) l.push(...markdownSeguimiento(informe.seguimiento));
  if (informe.consumo) l.push(...markdownConsumo(informe.consumo));
  l.push('## Cobertura');
  l.push(`- Revisado: ${informe.cobertura.revisado.join('; ') || '—'}`);
  l.push(`- **No revisado:** ${informe.cobertura.noRevisado.join('; ') || '—'}`);
  return l.join('\n');
}

